    15	    /// rejected at create/update time as a defence-in-depth guard against typo'd or fabricated values
    16	    /// (the admin dropdown is the only happy-path entry, but the API surface is public-Authenticated).
    17	    /// </summary>
    18	    private static readonly HashSet<string> AllowedProductTypes = new(StringComparer.Ordinal)
    19	    {
    20	        "PACKAGE",
    21	        "SINGLE_CLASS",
    22	        "MERCHANDISE",
    23	        "FREELANCE_PACKAGE",
    24	        "FREELANCE_SINGLE",
    25	    };
