    30	    {
    31	        _products = dbContext.GetCollection<Product>("Products");
    32	    }
    33	
    34	    public async Task<IEnumerable<Product>> GetAllProductsAsync()
    35	    {
    36	        return await _products.Find(_ => true).ToListAsync();
    37	    }
    38	
    39	    public async Task<Product?> GetProductByIdAsync(string id)
    40	    {
    41	        return await _products.Find(p => p.Id == id).FirstOrDefaultAsync();
    42	    }
