    44	    public async Task<Product> CreateProductAsync(Product product)
    45	    {
    46	        ValidateProductType(product);
    47	        await _products.InsertOneAsync(product);
    48	        return product;
    49	    }
    50	
    51	    public async Task UpdateProductAsync(string id, Product product)
    52	    {
    53	        ValidateProductType(product);
    54	        product.Id = id;
    55	        await _products.ReplaceOneAsync(p => p.Id == id, product);
    56	    }
    57	
    58	    public async Task DeleteProductAsync(string id)
    59	    {
    60	        var update = Builders<Product>.Update.Set(p => p.IsActive, false);
    61	        await _products.UpdateOneAsync(p => p.Id == id, update);
    62	    }
    63	
    64	    private static void ValidateProductType(Product product)
    65	    {
    66	        if (product == null) throw new ArgumentNullException(nameof(product));
    67	        if (string.IsNullOrWhiteSpace(product.Type))
    68	        {
    69	            throw new ArgumentException("Product.Type is required.", nameof(product));
    70	        }
    71	        if (!AllowedProductTypes.Contains(product.Type))
    72	        {
    73	            var allowed = string.Join(", ", AllowedProductTypes);
    74	            throw new ArgumentException(
    75	                $"Product.Type '{product.Type}' is not in the allowed set: {allowed}.",
    76	                nameof(product));
    77	        }
    78	    }
