using MongoDB.Driver;
using SoulPilates.Core.DTOs;
using SoulPilates.Core.Entities;
using SoulPilates.Core.Exceptions;
using SoulPilates.Core.Interfaces;
using SoulPilates.Infrastructure.Data;
using SoulPilates.Services.Documents;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Threading.Tasks;

namespace SoulPilates.Services;

public class InvoiceService : IInvoiceService
{
    private readonly IMongoCollection<Invoice> _invoices;
    private readonly IMongoCollection<Payment> _payments;
    private readonly IMongoCollection<ClientPackage> _clientPackages;
    private readonly IMongoCollection<Product> _products;
    private readonly IMongoCollection<Client> _clients;
    private readonly IMongoCollection<Partner> _partners;
    private readonly IMongoCollection<RefereePayout> _refereePayouts;
    private readonly IMongoCollection<Attendance> _attendances;
    private readonly IDocumentRenderer _documentRenderer;
    private readonly IEmailService _emailService;
    private readonly IMerchandiseSkuService _skuService;
    private readonly IAuditLogger _audit;

    public InvoiceService(MongoDbContext dbContext, IDocumentRenderer documentRenderer, IEmailService emailService, IMerchandiseSkuService skuService, IAuditLogger audit)
    {
        _invoices = dbContext.GetCollection<Invoice>("Invoices");
        _payments = dbContext.GetCollection<Payment>("Payments");
        _clientPackages = dbContext.GetCollection<ClientPackage>("ClientPackages");
        _products = dbContext.GetCollection<Product>("Products");
        _clients = dbContext.GetCollection<Client>("Clients");
        _partners = dbContext.GetCollection<Partner>("Partners");
        _refereePayouts = dbContext.GetCollection<RefereePayout>("RefereePayouts");
        _attendances = dbContext.GetCollection<Attendance>("Attendances");
        _documentRenderer = documentRenderer;
        _emailService = emailService;
        _skuService = skuService;
        _audit = audit;

        // P2-S10: unique (InvoiceId, PartnerId) so re-firing payment on the same
        // invoice replaces rather than duplicates the payout row.
        var keys = Builders<RefereePayout>.IndexKeys
            .Ascending(r => r.InvoiceId)
            .Ascending(r => r.PartnerId);
        _refereePayouts.Indexes.CreateOne(new CreateIndexModel<RefereePayout>(keys,
            new CreateIndexOptions { Unique = true, Name = "ux_invoice_partner" }));
    }

    public async Task<Invoice> CreateInvoiceAsync(Invoice invoice)
    {
        // Snapshot Product.Type onto each line BEFORE persisting. This is the
        // P5 financial-integrity fix: a later reclassification of a product
        // (e.g. moving it from PACKAGE → MERCHANDISE) must not retroactively
        // change MonthlyWashout.RevenueByCategory for the month this invoice

    // change MonthlyWashout.RevenueByCategory for the month this invoice
    // was issued in. We resolve all product ids in one round-trip.
    var productIdsForSnapshot = invoice.Lines
        .Where(l => !string.IsNullOrWhiteSpace(l.ProductId))
        .Select(l => l.ProductId!)
        .Distinct()
        .ToList();
    var snapshotTypeById = productIdsForSnapshot.Count == 0
        ? new Dictionary<string, string?>()
        : (await _products.Find(p => productIdsForSnapshot.Contains(p.Id)).ToListAsync())
            .ToDictionary(p => p.Id!, p => (string?)p.Type);

    // Populate per-line LineTotal so downstream consumers (receipt, reports)
    // don't need to re-derive it. Honours an explicitly-supplied LineDiscount.
    foreach (var line in invoice.Lines)
    {
        if (line.LineTotal == 0)
            line.LineTotal = (line.UnitPrice * line.Quantity) - line.LineDiscount;

        // Only set the snapshot if the caller didn't already populate it
        // (e.g. a migration importer reconstructing historical invoices).
        if (string.IsNullOrWhiteSpace(line.ProductTypeSnapshot)
            && !string.IsNullOrWhiteSpace(line.ProductId)
            && snapshotTypeById.TryGetValue(line.ProductId!, out var snapType))
        {
            line.ProductTypeSnapshot = snapType;
        }
    }

    invoice.TotalGross = invoice.Lines.Sum(l => l.UnitPrice * l.Quantity);
    invoice.TotalNet = invoice.TotalGross - invoice.TotalDiscount + invoice.TotalTax + invoice.OnlineFeeAmount;
    invoice.Status = "UNPAID";

    if (string.IsNullOrWhiteSpace(invoice.InvoiceNumber))
        invoice.InvoiceNumber = await GenerateInvoiceNumberAsync(invoice.IssueDate);

    await _invoices.InsertOneAsync(invoice);

    // P4-S04 — audit the new invoice. EntityLabel = the human-readable number
    // so the timeline reads "created INV-260511-0001" rather than an ObjectId.
    await _audit.LogAsync(
        action: "CREATE",
        entityType: "Invoice",
        entityId: invoice.Id!,
        entityLabel: invoice.InvoiceNumber,
        after: new
        {
            invoice.ClientId,
            invoice.InvoiceNumber,
            invoice.IssueDate,
            invoice.TotalGross,
            invoice.TotalDiscount,
            invoice.TotalTax,
            invoice.TotalNet,
            invoice.Status,
            LineCount = invoice.Lines?.Count ?? 0,
        });

    // Zero-net invoices (e.g. a 100%-off / free-gift promo that covers the
    // whole cart) have nothing to collect. The payment endpoint rejects a
    // zero amountPaid, so we finalise here instead: mark PAID and run the
    // same provisioning a real payment would trigger. Otherwise these sales
    // fail at checkout with a misleading "Payment failed".
    if (invoice.TotalNet <= 0m)
    {
        invoice.Status = "PAID";
        await _invoices.UpdateOneAsync(
            Builders<Invoice>.Filter.Eq(i => i.Id, invoice.Id),
            Builders<Invoice>.Update.Set(i => i.Status, "PAID"));

        await ProvisionPackagesFromInvoiceAsync(invoice);
        // Mirrors the payment path: may throw InsufficientStockException,
        // which the caller surfaces as a stock conflict.
        await DeductStockForMerchandiseLinesAsync(invoice);
    }

    return invoice;
}

public async Task<Invoice?> GetInvoiceByIdAsync(string id)
{
    return await _invoices.Find(i => i.Id == id).FirstOrDefaultAsync();
}

public async Task<IEnumerable<Invoice>> GetInvoicesByClientIdAsync(string clientId)
{
    return await _invoices.Find(i => i.ClientId == clientId).ToListAsync();
}

public async Task<IReadOnlyList<RecentInvoiceDto>> GetRecentInvoicesAsync(int limit = 5)
{
    // Grab the most recent invoices sorted by issue date descending.
    var invoices = await _invoices
        .Find(FilterDefinition<Invoice>.Empty)
        .SortByDescending(i => i.IssueDate)
        .Limit(limit)
        .ToListAsync();

    if (invoices.Count == 0)
        return Array.Empty<RecentInvoiceDto>();

    // Batch-resolve client names.
    var clientIds = invoices
        .Where(i => !string.IsNullOrWhiteSpace(i.ClientId))
        .Select(i => i.ClientId)
        .Distinct()
        .ToList();
    var clientNameMap = clientIds.Count == 0
        ? new Dictionary<string, string>()
        : (await _clients.Find(c => clientIds.Contains(c.Id)).ToListAsync())
            .ToDictionary(c => c.Id!, c => c.FullName ?? "Client");

    // Batch-resolve product names for a compact items summary.
    var allProductIds = invoices
        .SelectMany(i => i.Lines)
        .Where(l => !string.IsNullOrWhiteSpace(l.ProductId))
        .Select(l => l.ProductId!)
        .Distinct()
        .ToList();
    var productNameMap = allProductIds.Count == 0
        ? new Dictionary<string, string>()
        : (await _products.Find(p => allProductIds.Contains(p.Id)).ToListAsync())
            .ToDictionary(p => p.Id!, p => p.Name ?? "Item");

    return invoices.Select(inv =>
    {
        // Build a short items summary: "Group 10-Pack, Yoga Mat" or "3 items"
        var lineNames = inv.Lines
            .Select(l => !string.IsNullOrWhiteSpace(l.Description) ? l.Description : productNameMap.TryGetValue(l.ProductId ?? "", out var n) ? n : "Item")
            .ToList();
        var summary = lineNames.Count <= 2
            ? string.Join(", ", lineNames)
            : $"{lineNames.Count} items";

        return new RecentInvoiceDto
        {
            Id = inv.Id!,
            InvoiceNumber = inv.InvoiceNumber,
            ClientName = clientNameMap.TryGetValue(inv.ClientId ?? "", out var cn) ? cn : "Walk-in",
            IssueDate = inv.IssueDate,
            ItemsSummary = summary,
            TotalNet = inv.TotalNet,
            Status = inv.Status,
        };
    }).ToList();
}

public async Task<Payment> AddPaymentAsync(string invoiceId, Payment payment)
{
    var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync();
    if (invoice == null) throw new Exception("Invoice not found");

    payment.InvoiceId = invoiceId;
    await _payments.InsertOneAsync(payment);

    // Keep the client's lifetime value live — it drives VIP status. AmountPaid
    // is negative for refunds, so this both grows and shrinks correctly.
    if (!string.IsNullOrWhiteSpace(invoice.ClientId) && payment.AmountPaid != 0)
        await _clients.UpdateOneAsync(c => c.Id == invoice.ClientId,
            Builders<Client>.Update.Inc(c => c.LifetimeValue, payment.AmountPaid));

    var allPayments = await _payments.Find(p => p.InvoiceId == invoiceId).ToListAsync();
    var totalPaid = allPayments.Sum(p => p.AmountPaid);

    var previousStatus = invoice.Status;
    if (totalPaid >= invoice.TotalNet) {
        invoice.Status = "PAID";
    } else if (totalPaid > 0) {
        invoice.Status = "PARTIAL";
    }

    await _invoices.ReplaceOneAsync(i => i.Id == invoiceId, invoice);

    // P4-S04 — audit the payment itself plus a STATUS_CHANGE event when the
    // invoice transitions (UNPAID → PARTIAL/PAID, or PARTIAL → PAID).
    await _audit.LogAsync(
        action: "PAYMENT_RECEIVED",
        entityType: "Invoice",
        entityId: invoiceId,
        entityLabel: invoice.InvoiceNumber,
        metadata: new { payment.AmountPaid, payment.PaymentMethod, payment.PaymentDate },
        after: new { invoice.Status, totalPaid });

    if (previousStatus != invoice.Status)
    {
        await _audit.LogAsync(
            action: "STATUS_CHANGE",
            entityType: "Invoice",
            entityId: invoiceId,
            entityLabel: invoice.InvoiceNumber,
            before: new { Status = previousStatus },
            after: new { invoice.Status });
    }

    if (invoice.Status == "PAID" || invoice.Status == "PARTIAL")
    {
        await ProvisionPackagesFromInvoiceAsync(invoice);

        // Send the receipt email when the invoice transitions into PAID/PARTIAL
        // (i.e. on each genuine payment), so customers get a fresh PDF that
        // reflects the cumulative AmountReceived / AmountOwed at this moment.
        // Fire-and-forget: matches the booking-confirmation pattern; SMTP-disabled mode is silent.
        _ = TrySendReceiptEmailAsync(invoiceId);
    }

    // P2-S10: only emit the referee payout once the invoice fully settles.
    // Re-running on a partial→full transition is safe (unique index dedupes).
    if (invoice.Status == "PAID")
    {
        await UpsertRefereePayoutAsync(invoice);

        // P3-S14: deduct per-variant merchandise stock once, on the first
        // PAID transition. Idempotency latch via Invoice.StockDeductedAt so
        // re-firing on an already-paid invoice doesn't double-decrement.
        // Throws InsufficientStockException (→ HTTP 409 in controller) if
        // any line's SKU has gone below the required quantity since cart
        // assembly; partial decrements roll back before the throw.
        await DeductStockForMerchandiseLinesAsync(invoice);
    }

    // ── Sync Attendance record ──────────────────────────────────────────
    // When a booking-linked invoice receives a payment, sync AmountPaid
    // and AmountDueAtStudio back to the Attendance document so the
    // bookings list, roster, and class-detail panels reflect the true
    // settled state without a manual refresh or data mismatch.
    await SyncAttendancePaymentAsync(invoice, totalPaid);

    return payment;
}

/// <summary>
/// When a payment is recorded against a booking-linked invoice, sync the
/// cumulative totals back to each linked <see cref="Attendance"/> record so
/// that the bookings list, class roster, and detail panels reflect the true
/// settled state. Without this, the Attendance row retains its original
/// <c>AmountDueAtStudio</c> from booking-creation time forever.
/// </summary>
private async Task SyncAttendancePaymentAsync(Invoice invoice, decimal totalPaid)
{
    // Only booking-linked invoices have AttendanceId on their lines.
    var linkedAttendanceIds = invoice.Lines
        .Where(l => !string.IsNullOrWhiteSpace(l.AttendanceId))
        .Select(l => l.AttendanceId!)
        .Distinct()
        .ToList();

    if (linkedAttendanceIds.Count == 0) return;

    var balanceDue = Math.Max(0, invoice.TotalNet - totalPaid);

    foreach (var attId in linkedAttendanceIds)
    {
        var update = Builders<Attendance>.Update
            .Set(a => a.AmountPaid, totalPaid)
            .Set(a => a.AmountDueAtStudio, balanceDue);

        await _attendances.UpdateOneAsync(a => a.Id == attId, update);
    }
}

/// <summary>
/// P2-S10. If the invoice carries a <c>RefereePartnerId</c>, compute the
/// commission across eligible lines and upsert a single
/// <see cref="RefereePayout"/> row keyed on <c>(InvoiceId, PartnerId)</c>.
/// Zero-amount results delete any prior row (e.g. eligibility was rolled
/// back on the partner since the last payment).
/// </summary>
private async Task UpsertRefereePayoutAsync(Invoice invoice)
{
    if (string.IsNullOrWhiteSpace(invoice.RefereePartnerId)) return;

    var partner = await _partners.Find(p => p.Id == invoice.RefereePartnerId).FirstOrDefaultAsync();
    if (partner is null) return;

    // Resolve product types AND display names in one round-trip. The names
    // feed the per-line breakdown snapshot so the partner statement is
    // self-describing without re-joining Products later.
    var productIds = invoice.Lines
        .Where(l => !string.IsNullOrWhiteSpace(l.ProductId))
        .Select(l => l.ProductId!)
        .Distinct()
        .ToList();
    var products = productIds.Count == 0
        ? new List<Product>()
        : await _products.Find(p => productIds.Contains(p.Id)).ToListAsync();
    var typeById = products.ToDictionary(p => p.Id!, p => (string?)p.Type);
    var nameById = products.ToDictionary(p => p.Id!, p => p.Name ?? string.Empty);

    var (amount, breakdown) = RefereeCommissionCalculator.ComputeInvoiceCommissionWithBreakdown(
        partner, invoice.Lines, typeById, nameById);

    var existing = await _refereePayouts
        .Find(r => r.InvoiceId == invoice.Id && r.PartnerId == partner.Id)
        .FirstOrDefaultAsync();

    // Eligibility revoked → tear the old row down rather than leave a phantom.
    if (amount <= 0m)
    {
        if (existing is not null)
            await _refereePayouts.DeleteOneAsync(r => r.Id == existing.Id);
        return;
    }

    var row = new RefereePayout
    {
        Id = existing?.Id,
        PartnerId = partner.Id!,
        InvoiceId = invoice.Id!,
        InvoiceNumber = invoice.InvoiceNumber,
        Amount = amount,
        Year = invoice.IssueDate.Year,
        Month = invoice.IssueDate.Month,
        // Preserve the admin's mark-paid decision across re-emissions.
        PaidStatus = existing?.PaidStatus ?? "PENDING",
        PaidAt = existing?.PaidAt,
        CreatedAt = existing?.CreatedAt ?? DateTime.UtcNow,
        UpdatedAt = DateTime.UtcNow,

        // ── Snapshot block (P5 financial-integrity) ──
        // Capture name + tier ladder at emission time. A later edit to the
        // Partner.CommissionTiers (or even a rename) leaves prior payouts
        // untouched: the statement is reconstructible from this row alone.
        PartnerNameSnapshot = partner.BusinessName ?? string.Empty,
        TiersSnapshot = partner.CommissionTiers.Select(t => new PartnerCommissionTier
        {
            MinPackagesQty = t.MinPackagesQty,
            CommissionPercentage = t.CommissionPercentage,
        }).ToList(),
        LineBreakdown = breakdown,
    };

    if (existing is null)
        await _refereePayouts.InsertOneAsync(row);
    else
        await _refereePayouts.ReplaceOneAsync(r => r.Id == existing.Id, row);
}

/// <summary>
/// Best-effort receipt email dispatch. Runs after payment commit so the in-flight
/// HTTP response is not blocked on SMTP latency. Any exception is swallowed and logged
/// because email is non-critical relative to the payment record itself.
/// </summary>
private async Task TrySendReceiptEmailAsync(string invoiceId)
{
    try
    {
        var (model, pdf) = await BuildReceiptAsync(invoiceId);
        if (string.IsNullOrWhiteSpace(model.ClientEmail)) return;

        await _emailService.SendReceiptAsync(model.ClientEmail!, model.ClientName, model, pdf);
    }
    catch (Exception ex)
    {
        Console.WriteLine($"[InvoiceService] Receipt email dispatch failed for invoice '{invoiceId}': {ex.Message}");
    }
}

public async Task<byte[]> RenderReceiptPdfAsync(string invoiceId)
{
    var (_, pdf) = await BuildReceiptAsync(invoiceId);
    return pdf;
}

/// <summary>
/// Compose the receipt model and render the PDF in one shot. Returned together
/// so the email path doesn't have to re-query Mongo to obtain client metadata
/// after the bytes are produced.
/// </summary>
private async Task<(InvoiceReceiptModel Model, byte[] Pdf)> BuildReceiptAsync(string invoiceId)
{
    var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync()
        ?? throw new InvalidOperationException($"Invoice '{invoiceId}' not found.");

    var client = !string.IsNullOrWhiteSpace(invoice.ClientId)
        ? await _clients.Find(c => c.Id == invoice.ClientId).FirstOrDefaultAsync()
        : null;

    // Resolve a friendly description per line (product name beats raw ObjectId in a receipt).
    var productIds = invoice.Lines
        .Where(l => !string.IsNullOrWhiteSpace(l.ProductId))
        .Select(l => l.ProductId)
        .Distinct()
        .ToList();

    var productMap = productIds.Count > 0
        ? (await _products.Find(p => productIds.Contains(p.Id!)).ToListAsync())
            .ToDictionary(p => p.Id!, p => p.Name)
        : new Dictionary<string, string>();

    var payments = await _payments.Find(p => p.InvoiceId == invoiceId).ToListAsync();

    var model = new InvoiceReceiptModel
    {
        InvoiceNumber = string.IsNullOrWhiteSpace(invoice.InvoiceNumber) ? "—" : invoice.InvoiceNumber,
        IssueDate = invoice.IssueDate,
        Status = invoice.Status,
        Notes = invoice.Notes,
        ClientName = client?.FullName ?? "Walk-in Client",
        ClientPhone = client?.PhoneNumber,
        ClientEmail = client?.Email,
        TotalGross = invoice.TotalGross,
        TotalDiscount = invoice.TotalDiscount,
        TotalTax = invoice.TotalTax,
        TotalNet = invoice.TotalNet,
        OnlineFeeAmount = invoice.OnlineFeeAmount,
        AmountReceived = payments.Sum(p => p.AmountPaid),
        Lines = invoice.Lines
            .OrderBy(l => l.CreatedAt)
            .Select(l => new InvoiceReceiptLine
            {
                Description = !string.IsNullOrWhiteSpace(l.Description)
                    ? l.Description
                    : (productMap.TryGetValue(l.ProductId ?? string.Empty, out var name) && !string.IsNullOrWhiteSpace(name))
                        ? name
                        : "Item",
                Quantity = l.Quantity,
                UnitPrice = l.UnitPrice,
                LineDiscount = l.LineDiscount,
                LineTotal = l.LineTotal > 0 ? l.LineTotal : (l.UnitPrice * l.Quantity) - l.LineDiscount,
            })
            .ToList(),
        Payments = payments
            .OrderBy(p => p.PaymentDate)
            .Select(p => new InvoiceReceiptPayment
            {
                PaymentDate = p.PaymentDate,
                AmountPaid = p.AmountPaid,
                PaymentMethod = p.PaymentMethod,
            })
            .ToList(),
        StudioName = "Soul Pilates Da Nang",
        // Studio contact lines stay generic until a SettingsService surface is plumbed in P2-S01.
        StudioContact = "soulpilates.com.vn",
    };

    model.AmountOwed = Math.Max(0, model.TotalNet - model.AmountReceived);

    var pdf = _documentRenderer.Render(new InvoiceReceiptDocument(), model);
    return (model, pdf);
}

internal async Task ProvisionPackagesFromInvoiceAsync(Invoice invoice)
{
    foreach(var line in invoice.Lines)
    {
        var product = await _products.Find(p => p.Id == line.ProductId).FirstOrDefaultAsync();
        if (product == null) continue;

        if (product.Type != "PACKAGE" && product.Type != "FREELANCE_PACKAGE") continue;

        var credits = product.Credits > 0 ? product.Credits : 1;
        var validityDays = product.ValidityDays;

        // A single invoice line can carry Quantity > 1 (the POS merges
        // repeat purchases of the same product into one line). Each unit
        // must become its own wallet, otherwise buying "2× Group Package"
        // only activates a single package. Value-per-class is derived from
        // the per-unit price so it stays correct regardless of quantity.
        var units = line.Quantity > 0 ? line.Quantity : 1;
        var perUnitTotal = units > 0 ? line.LineTotal / units : line.LineTotal;

        for (var i = 0; i < units; i++)
        {
            var newWallet = new ClientPackage
            {
                ClientId = invoice.ClientId,
                InvoiceLineId = line.Id,
                Format = product.FormatRestriction,
                TotalCredits = credits,
                CreditsRemaining = credits,
                ActivationDate = DateTime.UtcNow,
                // ValidityDays == 0 → open-ended package, no expiry date.
                ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
                Status = "ACTIVE",
                FractionalValuePerClass = credits > 0 ? (perUnitTotal / credits) : 0
            };

            await _clientPackages.InsertOneAsync(newWallet);

            // A package with "includes one free private class" grants a separate
            // PRIVATE-format credit, one per package unit, with the same validity
            // window. The instructor who later teaches this private class is paid
            // the SAME per-class commission base as the package's group credits
            // (owner rule): value it at the parent package's per-class value
            // (perUnitTotal / credits), NOT 0 and NOT the private drop-in. A 0
            // here would fall through to the drop-in in PayrollService's commission
            // resolution, over-paying the instructor.
            if (product.IncludesFreePrivateClass)
            {
                await _clientPackages.InsertOneAsync(new ClientPackage
                {
                    ClientId = invoice.ClientId,
                    InvoiceLineId = line.Id,
                    Format = "PRIVATE",
                    TotalCredits = 1,
                    CreditsRemaining = 1,
                    ActivationDate = DateTime.UtcNow,
                    ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
                    Status = "ACTIVE",
                    FractionalValuePerClass = credits > 0 ? (perUnitTotal / credits) : 0m,
                    SourceNote = "FREE_PRIVATE:" + line.Id,
                });
            }
        }
    }
}

/// <summary>
/// Produces a human-readable, monotonically-ordered invoice number
/// in the form <c>SP-INV-YYMMDD-NNNN</c>, where NNNN is the next sequence
/// for that calendar day (UTC). Format mirrors the booking-reference style
/// already documented in <c>_AGENT_NOTES.md</c>.
/// </summary>
private async Task<string> GenerateInvoiceNumberAsync(DateTime issueDate)
{
    var dayPrefix = $"SP-INV-{issueDate.ToUniversalTime():yyMMdd}-";

    // Count existing invoices with the same prefix to derive the next sequence.
    // Uses a regex match on InvoiceNumber so we don't need a separate counter collection
    // (acceptable given studio scale; will be revisited if sequencing becomes a hot path).
    var filter = Builders<Invoice>.Filter.Regex(
        i => i.InvoiceNumber,
        new MongoDB.Bson.BsonRegularExpression($"^{dayPrefix}"));

    var existingForDay = await _invoices.CountDocumentsAsync(filter);
    var sequence = (existingForDay + 1).ToString("D4", CultureInfo.InvariantCulture);

    return dayPrefix + sequence;
}
