160	            return BadRequest(new { message = "delta must be non-zero." });
161	        if (string.IsNullOrWhiteSpace(req.Reason))
162	            return BadRequest(new { message = "A reason is required for credit adjustments." });
163	
164	        var ok = await _walletService.AdjustCreditAsync(packageId, req.Delta, req.Reason);
165	        if (!ok)
166	            return BadRequest(new { message = "Adjustment failed. Package not found, package is frozen/expired, or removal would exceed available credits." });
167	
168	        // Optional notification — email failure must never roll back the
169	        // adjustment (same non-throwing contract as all other email dispatch
170	        // paths in this codebase). We await directly rather than Task.Run to
171	        // keep the call within the HTTP request scope — both _clientService
172	        // and _emailService are scoped and would be disposed after the
173	        // response completes.
174	        if (req.SendNotification && !string.IsNullOrWhiteSpace(req.ClientId))
