/// Loads the chosen <see cref="Product"/> and mints a <see cref="ClientPackage"/> from its
/// <c>Credits</c> / <c>ValidityDays</c>. The minting logic intentionally MIRRORS
/// <c>InvoiceService.ProvisionPackagesFromInvoiceAsync</c>:
/// <list type="bullet">
///   <item>only <c>Type == "PACKAGE"</c> products provision a wallet;</item>
///   <item>credits floor at 1 (<c>product.Credits &gt; 0 ? product.Credits : 1</c>);</item>
///   <item><c>ValidityDays == 0</c> =&gt; <c>ExpiryDate</c> null / never-expires (SPM-38 fix).</item>
/// </list>
/// Because this is a comp grant there is no invoice/payment behind it, so
/// <see cref="ClientPackage.InvoiceLineId"/> is left null and
/// <see cref="ClientPackage.FractionalValuePerClass"/> is 0 (no revenue attribution).
/// </para>
/// <para>
/// A single governance <see cref="AuditLog"/> row is written via <see cref="IAuditLogger"/>
/// (non-throwing per its contract) — the same pattern the adjust-credit path uses — capturing
/// the granting actor, the comp grant details and the mandatory <paramref name="reason"/>.
/// </para>
/// Returns the minted package, or <c>null</c> when the product is not found or is not a PACKAGE.
/// </summary>
public async Task<ClientPackage?> GrantPackageAsync(string clientId, string productId, string reason)
{
    if (string.IsNullOrWhiteSpace(clientId)) return null;
    if (string.IsNullOrWhiteSpace(productId)) return null;

    var product = await _products.Find(p => p.Id == productId).FirstOrDefaultAsync();
    if (product == null) return null;

    // Mirror ProvisionPackagesFromInvoiceAsync: only PACKAGE products create wallets.
    if (product.Type != "PACKAGE") return null;

    var credits = product.Credits > 0 ? product.Credits : 1;
    var validityDays = product.ValidityDays;

    var newWallet = new ClientPackage
    {
        ClientId = clientId,
        // Comp grant — no invoice line behind it.
        InvoiceLineId = null,
        Format = product.FormatRestriction,
        TotalCredits = credits,
        CreditsRemaining = credits,
        ActivationDate = DateTime.UtcNow,
        // ValidityDays == 0 → open-ended package, no expiry date (SPM-38).
        ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
        Status = "ACTIVE",
        // Free comp grant: no revenue, so the per-class fractional value is 0.
        FractionalValuePerClass = 0
    };

    await _clientPackages.InsertOneAsync(newWallet);

    // Mirror ProvisionPackagesFromInvoiceAsync: a package that includes one
    // free private class grants a separate PRIVATE credit (value 0).
    if (product.IncludesFreePrivateClass)
    {
        await _clientPackages.InsertOneAsync(new ClientPackage
        {
            ClientId = clientId,
            InvoiceLineId = null,
            Format = "PRIVATE",
            TotalCredits = 1,
            CreditsRemaining = 1,
            ActivationDate = DateTime.UtcNow,
            ExpiryDate = validityDays > 0 ? (DateTime?)DateTime.UtcNow.AddDays(validityDays) : null,
            Status = "ACTIVE",
            FractionalValuePerClass = 0,
            SourceNote = "FREE_PRIVATE:grant:" + (newWallet.Id ?? clientId),
        });
    }

    // ── Governance audit row ──────────────────────────────────────────

///   • No product ID is pinned for the session's format, OR
///   • The pinned product no longer exists / is inactive, OR
///   • The customer already owns an active package and
///     <see cref="GlobalSettings.UpsellHideForActivePackageHolders"/> is true.
/// </summary>
private async Task<List<UpsellSuggestion>> BuildUpsellSuggestionsAsync(
    string sessionFormat,
    decimal dropInPrice,
    string? clientId,
    GlobalSettings settings)
{
    if (!settings.EnableCheckoutPackageUpsell) return new List<UpsellSuggestion>();

    // Pick the pinned product ID for this session format.
    var pinnedId = sessionFormat switch
    {
        "PRIVATE" => settings.UpsellPackageIdPrivate,
        "MIXED"   => settings.UpsellPackageIdMixed,
        _         => settings.UpsellPackageIdGroup, // GROUP and anything else
    };

    if (string.IsNullOrWhiteSpace(pinnedId)) return new List<UpsellSuggestion>();

    // Hide-when-owner check.
    if (settings.UpsellHideForActivePackageHolders && !string.IsNullOrWhiteSpace(clientId))
    {
        var ownsActive = await _clientPackages
            .Find(p => p.ClientId == clientId
                       && p.Status == "ACTIVE"
                       && p.CreditsRemaining > 0
                       && (p.ExpiryDate == null || p.ExpiryDate > DateTime.UtcNow))
            .AnyAsync();
        if (ownsActive) return new List<UpsellSuggestion>();
    }

    // Load the pinned product. Never surface a product hidden from the
    // online shop as the checkout upsell.
    var product = await _products
        .Find(p => p.Id == pinnedId && p.IsActive && p.Type == "PACKAGE" && p.Credits > 0 && !p.HiddenFromOnline)
        .FirstOrDefaultAsync();

    if (product == null) return new List<UpsellSuggestion>();

    var perClass = Math.Round(product.BasePrice / product.Credits);
    var savingsPct = dropInPrice > 0
        ? (int)Math.Round((dropInPrice - perClass) * 100m / dropInPrice)
        : 0;

    return new List<UpsellSuggestion>
    {
        new UpsellSuggestion
        {
            ProductId       = product.Id ?? "",
            Name            = product.Name,
            Description     = product.Description,
            FormatRestriction = product.FormatRestriction ?? "NONE",
            BasePrice       = product.BasePrice,
            Credits         = product.Credits,
            ValidityDays    = product.ValidityDays,
            PricePerClass   = perClass,
            SavingsPercentage = savingsPct,
        }
    };
}

/// <summary>
/// BOGO ("Buy 1 Get 1 Free") reward: when a booking made with the BOGO offer
/// is confirmed, grant the client one free GROUP class credit valid 7 days.
/// Idempotent-ish — fires once at the RESERVED→BOOKED transition. Best-effort:
/// never throws into the booking flow.
/// </summary>
private async Task GrantBogoCreditIfEligibleAsync(Attendance? attendance)
{
    try
    {
        if (attendance is null) return;
        if (!string.Equals(attendance.PromoCode, "BOGO", StringComparison.OrdinalIgnoreCase)) return;
        if (string.IsNullOrWhiteSpace(attendance.ClientId)) return;
        // Guard against a duplicate grant if this transition runs twice.
        var already = await _clientPackages
            .Find(p => p.ClientId == attendance.ClientId && p.SourceNote == "BOGO:" + attendance.Id)
            .AnyAsync();
        if (already) return;

        await _clientPackages.InsertOneAsync(new ClientPackage
        {
            ClientId = attendance.ClientId,
            Format = "GROUP",
            TotalCredits = 1,
            CreditsUsed = 0,
            CreditsRemaining = 1,
            ActivationDate = DateTime.UtcNow,
            ExpiryDate = DateTime.UtcNow.AddDays(7),
            Status = "ACTIVE",
            FractionalValuePerClass = 0m,
            SourceNote = "BOGO:" + attendance.Id,
        });
    }
    catch { /* analytics/reward must never break a booking */ }
}

