 86	                p.IsActive && p.Type == "SINGLE_CLASS" &&
 87	                string.Equals(p.FormatRestriction, format, StringComparison.OrdinalIgnoreCase));
 88	            return single?.BasePrice ?? 0m;
 89	        }
 90	
 91	        var featured = products
 92	            .Where(p => p.IsActive && !p.HiddenFromOnline && p.IsFeatured && p.Type == "PACKAGE")
 93	            .OrderBy(p => p.BasePrice)
 94	            .Select(p =>
 95	            {
 96	                var perClass = p.Credits > 0 ? Math.Round(p.BasePrice / p.Credits) : p.BasePrice;
 97	                var dropIn = DropInFor(p.FormatRestriction);
 98	                var savePercent = (dropIn > 0 && perClass < dropIn)
 99	                    ? (int)Math.Round((1 - (perClass / dropIn)) * 100)
100	                    : 0;
101	                return new
102	                {
103	                    id = p.Id,
104	                    name = p.Name,
105	                    description = p.Description,
106	                    formatRestriction = p.FormatRestriction,
107	                    basePrice = p.BasePrice,
108	                    credits = p.Credits,
109	                    validityDays = p.ValidityDays,
110	                    pricePerClass = perClass,
111	                    dropInPrice = dropIn,
112	                    savePercent,
113	                    freeSocks = p.FreeSocks,
114	                    includesFreePrivateClass = p.IncludesFreePrivateClass,
115	                };
116	            });
117	        return Ok(featured);
118	    }
