120	    /// <summary>
121	    /// Create a draft invoice for the chosen package and a Stripe PaymentIntent
122	    /// to settle it. Auth-gated to the <c>Customer</c> role — no guests.
123	    /// </summary>
124	    [HttpPost("checkout")]
125	    [Authorize(Roles = "Customer")]
126	    public async Task<IActionResult> Checkout([FromBody] CheckoutRequest request)
127	    {
128	        if (string.IsNullOrWhiteSpace(request.ProductId))
129	            return BadRequest(new { message = "productId is required." });
130	
131	        var clientId = User.FindFirstValue("clientId");
132	        if (string.IsNullOrWhiteSpace(clientId))
133	            return Unauthorized(new { message = "Customer account not linked to a client." });
134	
135	        var product = await _productService.GetProductByIdAsync(request.ProductId);
136	        if (product == null) return NotFound(new { message = "Package not found." });
137	
138	        // Only PACKAGE products can go through the customer purchase flow.
139	        // MERCHANDISE must be sold via the POS.
140	        if (product.Type != "PACKAGE")
141	            return BadRequest(new { message = "Only PACKAGE products can be purchased through this flow." });
142	        if (!product.IsActive)
143	            return BadRequest(new { message = "This package is no longer available." });
144	        if (product.HiddenFromOnline)
145	            return BadRequest(new { message = "This package is no longer available." });
146	        if (product.BasePrice <= 0)
147	            return BadRequest(new { message = "Package has no purchasable price." });
148	
149	        // Build the draft invoice. PARTIAL is intentional rather than UNPAID —
150	        // it mirrors the POS shape so AddPaymentAsync can later flip it to PAID
151	        // via the standard provisioning path. ProductTypeSnapshot is stamped by
152	        // InvoiceService.CreateInvoiceAsync so historical washouts stay correct.
153	        // Online payment fee (VAT, online only) — same surcharge customers pay on
154	        // online class bookings. Applied to the package price; CreateInvoiceAsync
155	        // folds OnlineFeeAmount into TotalNet, so the customer is billed base + VAT
156	        // and the receipt itemises it.
157	        var feePct = (await _settingsService.GetAsync()).OnlinePaymentFeePercentage;
158	        var onlineFee = feePct > 0 ? Math.Round(product.BasePrice * feePct / 100m) : 0m;
159	
160	        var invoice = new Invoice
161	        {
162	            ClientId = clientId,
163	            IssueDate = DateTime.UtcNow,
164	            Status = "PENDING",
165	            Notes = $"Online package purchase — {product.Name}",
166	            OnlineFeeAmount = onlineFee,
167	            Lines = new System.Collections.Generic.List<InvoiceLine>
168	            {
169	                new InvoiceLine
170	                {
171	                    ProductId = product.Id!,
172	                    Quantity = 1,
173	                    UnitPrice = product.BasePrice,
174	                    LineDiscount = 0,
175	                    LineTotal = product.BasePrice,
176	                }
177	            }
178	        };
179	
180	        var created = await _invoiceService.CreateInvoiceAsync(invoice);
181	
182	        // Hand off to PaymentService — it handles dev-mode mocks, Stripe live,
183	        // audit logging, and metadata routing for the webhook.
184	        var intent = await _paymentService.CreatePackagePurchaseIntentAsync(created.Id!);
185	
186	        await _audit.LogAsync(
187	            action: "PACKAGE_PURCHASE_CHECKOUT",
188	            entityType: "Invoice",
189	            entityId: created.Id!,
190	            entityLabel: created.InvoiceNumber,
191	            metadata: new { product.Id, product.Name, product.BasePrice, clientId });
192	
193	        return Ok(new
194	        {
195	            invoiceId = created.Id,
196	            invoiceNumber = created.InvoiceNumber,
197	            paymentIntentId = intent.PaymentIntentId,
198	            clientSecret = intent.ClientSecret,
199	            useEmbeddedCheckout = intent.UseEmbeddedCheckout,
200	            checkoutSessionId = intent.CheckoutSessionId,
201	            amount = intent.Amount,
202	            baseAmount = intent.SessionFee,
203	            feeAmount = intent.FeeAmount,
204	            feePercentage = intent.FeePercentage,
205	            currency = intent.Currency,
206	            publishableKey = intent.PublishableKey,
207	            productName = product.Name,
208	            credits = product.Credits,
209	            validityDays = product.ValidityDays,
210	        });
211	    }
