213	    /// <summary>
214	    /// Dev-mode confirm hook — called by the front-end after the mock Stripe
215	    /// Elements promise resolves. In production this is a NO-OP because the
216	    /// real Stripe webhook fires <c>payment_intent.succeeded</c> and the
217	    /// webhook handler invokes <see cref="IPaymentService.MarkInvoicePaidAsync"/>
218	    /// directly. We deliberately accept the <c>invoiceId</c> from the client
219	    /// (and re-verify ownership against the JWT) because mock intents don't
220	    /// have Metadata we can recover the invoiceId from.
221	    /// </summary>
222	    [HttpPost("confirm")]
223	    [Authorize(Roles = "Customer")]
224	    public async Task<IActionResult> Confirm([FromBody] ConfirmRequest request)
225	    {
226	        if (string.IsNullOrWhiteSpace(request.InvoiceId))
227	            return BadRequest(new { message = "invoiceId is required." });
228	        if (string.IsNullOrWhiteSpace(request.PaymentIntentId))
229	            return BadRequest(new { message = "paymentIntentId is required." });
230	
231	        var clientId = User.FindFirstValue("clientId");
232	        if (string.IsNullOrWhiteSpace(clientId)) return Unauthorized();
233	
234	        // Defence-in-depth: confirm that the JWT principal owns this invoice
235	        // before we let them flip it to PAID. Without this, a logged-in
236	        // customer could in theory settle someone else's pending invoice.
237	        var invoice = await _invoices.Find(i => i.Id == request.InvoiceId).FirstOrDefaultAsync();
238	        if (invoice == null) return NotFound(new { message = "Invoice not found." });
239	        if (invoice.ClientId != clientId)
240	            return StatusCode(403, new { message = "Invoice does not belong to this customer." });
241	
242	        // For real Stripe intents, MarkInvoicePaidAsync recovers the invoiceId
243	        // from intent.Metadata and is the safe path. For mock intents we route
244	        // through the internal helper.
245	        bool ok;
246	        if (request.PaymentIntentId.StartsWith("pi_pkg_mock_", StringComparison.Ordinal))
247	        {
248	            ok = await _paymentService.MarkInvoicePaidByIdAsync(request.InvoiceId, request.PaymentIntentId);
249	        }
250	        else
251	        {
252	            ok = await _paymentService.MarkInvoicePaidAsync(request.PaymentIntentId);
253	        }
254	
255	        return Ok(new { success = ok });
256	    }
