 53	    public async Task<MigrationReport> RunAsync(string? csvPath, bool commit, CancellationToken ct)
 54	    {
 55	        var report = new MigrationReport { CommandName = Name, Committed = commit };
 56	
 57	        if (string.IsNullOrWhiteSpace(csvPath))
 58	        {
 59	            report.AddIssue(0, null, MigrationIssueSeverity.Error, "Missing required --csv <path>.");
 60	            report.FinishedAt = DateTime.UtcNow;
