 70	        // --- Pre-load product lookup table -------------------------------
 71	        // We pull every product into memory once. Product master is small
 72	        // (\u226450 rows) so this avoids per-row Mongo round-trips. Key on the
 73	        // lowercased trimmed name for case-insensitive match.
 74	        var allProducts = await _products.Find(_ => true).ToListAsync(ct);
 75	        var productByName = allProducts
 76	            .GroupBy(p => p.Name.Trim().ToLowerInvariant())
