 80	        {
 81	            HasHeaderRecord = true,
 82	            PrepareHeaderForMatch = args => (args.Header ?? string.Empty).Trim().ToLowerInvariant(),
 83	            MissingFieldFound = null,
 84	            BadDataFound = null,
 85	        };
