 87	        List<PackageCsvRow> rows;
 88	        try
 89	        {
 90	            using var reader = new StreamReader(csvPath);
 91	            using var csv = new CsvReader(reader, csvConfig);
 92	            rows = csv.GetRecords<PackageCsvRow>().ToList();
 93	        }
 94	        catch (Exception ex)
 95	        {
 96	            report.AddIssue(0, null, MigrationIssueSeverity.Error,
 97	                $"Failed to parse CSV ({ex.GetType().Name}): {ex.Message}");
 98	            report.FinishedAt = DateTime.UtcNow;
 99	            return report;
100	        }
101	
102	        var seenInBatch = new HashSet<string>(StringComparer.Ordinal);
103	
104	        for (int i = 0; i < rows.Count; i++)
105	        {
106	            ct.ThrowIfCancellationRequested();
107	            var row = rows[i];
108	            var rowNum = i + 1;
109	
110	            // 1) Required-field gate.
111	            var receiptId = (row.receipt_id ?? string.Empty).Trim();
112	            var packageId = (row.package_id ?? string.Empty).Trim();
113	            var clientSheetId = (row.client_sheet_id ?? string.Empty).Trim();
114	            var packageType = (row.package_type ?? string.Empty).Trim();
115	
116	            if (receiptId.Length == 0 || packageId.Length == 0)
117	            {
118	                // Filler/placeholder rows with no identifiers — skip silently
119	                report.Skipped++;
120	                continue;
121	            }
122	            if (clientSheetId.Length == 0)
123	            {
124	                // No client reference — skip silently
125	                report.Skipped++;
126	                continue;
127	            }
128	            if (packageType.Length == 0)
129	            {
130	                // Filler/placeholder row with no data — skip silently
131	                report.Skipped++;
132	                continue;
133	            }
134	
135	            // 2) Idempotency
136	            var key = ExternalKeyPrefix + receiptId + ":" + packageId;
137	            if (!seenInBatch.Add(key))
138	            {
139	                report.AddIssue(rowNum, null, MigrationIssueSeverity.Info,
140	                    $"Duplicate of an earlier row in this batch ({key}); skipped.");
141	                report.Skipped++;
142	                continue;
143	            }
144	            var alreadyImported = await _tracker.FindAsync(CollectionName, key, ct);
145	            if (alreadyImported != null)
146	            {
147	                report.AddIssue(rowNum, null, MigrationIssueSeverity.Info,
148	                    $"Already imported on {alreadyImported.ImportedAt:yyyy-MM-dd HH:mm}Z; skipped.");
149	                report.Skipped++;
150	                continue;
151	            }
152	
153	            // 3) Cross-collection lookups -------------------------------------
154	            // 3a) Client by sheet ID via the migration log.
155	            var clientKey = ClientExternalKeyPrefix + clientSheetId;
156	            var clientLog = await _tracker.FindAsync(ClientCollectionName, clientKey, ct);
157	            if (clientLog == null)
