/// <summary>
/// BOGO reward grant (studio-payment path). Mirrors the Stripe-path grant in
/// PaymentService: one free GROUP credit (7-day expiry, value 0), idempotent via
/// ClientPackage.SourceNote. Best-effort — never throws into the payment flow.
/// </summary>
private async Task GrantBogoCreditIfEligibleAsync(Attendance attendance)
{
    try
    {
        if (!string.Equals(attendance.PromoCode, "BOGO", StringComparison.OrdinalIgnoreCase)) return;
        if (string.IsNullOrWhiteSpace(attendance.ClientId)) return;
        var note = "BOGO:" + attendance.Id;
        var already = await _clientPackages.Find(p => p.ClientId == attendance.ClientId && p.SourceNote == note).AnyAsync();
        if (already) return;

        await _clientPackages.InsertOneAsync(new ClientPackage
        {
            ClientId = attendance.ClientId,
            Format = "GROUP",
            TotalCredits = 1,
            CreditsUsed = 0,
            CreditsRemaining = 1,
            ActivationDate = DateTime.UtcNow,
            ExpiryDate = DateTime.UtcNow.AddDays(7),
            Status = "ACTIVE",
            FractionalValuePerClass = 0m,
            SourceNote = note,
        });
    }
    catch { /* reward must never break payment */ }
}

