public async Task<object> WalkInCheckoutAsync(
    string sessionId, string clientId, decimal amount,
    string paymentMethod, string? notes,
    IInvoiceService invoiceService,
    string? packageInstanceId = null,
    decimal? referralDiscountPct = null)
{
    if (amount < 0) throw new InvalidOperationException("Amount cannot be negative.");

    // 1. Validate session exists and has capacity
    var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync()
        ?? throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found.");

    if (session.Status != "SCHEDULED")
        throw new BusinessRuleException("BOOKING.SESSION_NOT_AVAILABLE", "This session is no longer available.");

    // Atomically claim the seat up-front so concurrent POS/online bookings of
    // the last spot can't overbook. Released again if a later step throws.
    if (!await TryClaimSessionCapacityAsync(sessionId, 1))
        throw new BusinessRuleException("BOOKING.SESSION_FULL", "This class is full. No spots available.");

    // 2. Duplicate-booking guard is intentionally skipped here.
    // The POS uses a lineKey (class::sessionId) to prevent accidentally
    // double-adding the same item. Reaching this endpoint means the
    // receptionist deliberately wants to add a second (or further) walk-in
    // seat for the same client on the same session — which is a valid
    // use-case (e.g., the client originally booked 1 seat online and now
    // walks in to buy another). The backend simply creates a second
    // Attendance row with BookingSource = "WALK_IN".

    // 3. Resolve client info for denormalized fields
    var client = await _clients.Find(c => c.Id == clientId).FirstOrDefaultAsync();
    var clientName = client?.FullName ?? "Walk-in";
    var clientPhone = client?.PhoneNumber;
    var clientEmail = client?.Email;

    // 4. Handle PACKAGE_CREDIT flow
    var isCredit = string.Equals(paymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase);
    string? resolvedPackageId = packageInstanceId;

    if (isCredit)
    {
        // Auto-match package if not specified
        if (string.IsNullOrWhiteSpace(resolvedPackageId))
        {
            var packages = await _walletService.GetActivePackagesForClientAsync(clientId, session.Format);
            var pkg = packages.FirstOrDefault();
            if (pkg == null)
            {
                await ReleaseSessionCapacityAsync(sessionId, 1);
                throw new BusinessRuleException("BOOKING.NO_PACKAGE",
                    $"No active {session.Format} package found for this client.");
            }
            resolvedPackageId = pkg.Id;
        }

        // Deduct credit BEFORE creating the attendance so we fail fast
        var deducted = await _walletService.DeductCreditAsync(clientId, session.Format, "pos-walkin-" + sessionId);
        if (!deducted)
        {
            await ReleaseSessionCapacityAsync(sessionId, 1);
            throw new BusinessRuleException("BOOKING.CREDIT_DEDUCTION_FAILED",
                "Insufficient credits or package not available. Please check the client's wallet.");
        }
    }

    // 5. Determine drop-in price from session snapshot.
    //    If a partner referral discount was applied, the net price is the
    //    basis for amountDue so the studio never expects the discounted
    //    portion as outstanding balance.
    var basePrice = session.DropInPrice ?? 0m;
    var clampedDiscountPct = referralDiscountPct.HasValue
        ? Math.Clamp(referralDiscountPct.Value, 0m, 1m)
        : 0m;
    var discountAmount = Math.Round(basePrice * clampedDiscountPct, 0, MidpointRounding.AwayFromZero);
    var expectedPrice = basePrice - discountAmount;   // net class price after referral
    var actualPaid = isCredit ? 0m : amount;
    var amountDue = isCredit ? 0m : Math.Max(0, expectedPrice - amount);

    // 6. Create the Attendance (booking)
    var attendance = new Attendance
    {
        CalendarSessionId = sessionId,
        ClientId = clientId,
        Status = "BOOKED",
        BookedAt = DateTime.UtcNow,
        BookingReference = GenerateBookingReference(),
        ClientName = clientName,
        ClientPhone = clientPhone,
        ClientEmail = clientEmail,
        BookingSource = "WALK_IN",
        PaymentMethod = isCredit ? "PACKAGE_CREDIT" : "PAY_AT_STUDIO",
        PackageInstanceId = isCredit ? resolvedPackageId : null,
        AmountPaid = actualPaid,
        AmountDueAtStudio = amountDue,
        Quantity = 1,
        // Store the referral discount so the payroll service can apply
        // it when computing the instructor's commission.
        ReferralDiscountPct = clampedDiscountPct > 0m ? clampedDiscountPct : null,
    };
    // Seat already claimed atomically above; roll it back (and the credit) if
    // the attendance insert fails so capacity/credit never drift.
    try
    {
        await _attendances.InsertOneAsync(attendance);
    }
    catch
    {
        await ReleaseSessionCapacityAsync(sessionId, 1);
        if (isCredit && !string.IsNullOrWhiteSpace(resolvedPackageId))
            await _walletService.RefundCreditAsync(resolvedPackageId, "pos-walkin-" + sessionId);
        throw;
    }

    // P5-PWA — a POS walk-in sale is a real booking; notify like any booking.
    // A genuine walk-in booking ends the client's lapse — clear the win-back throttle.
    await ClearWinBackThrottleAsync(clientId);
    FireAndForgetManualBookingPush(attendance, session);
    // Manual booking confirmation email (board: "Manual booking confirmation email").
    FireAndForgetManualBookingEmail(attendance, session);

    // 8. Create linked Invoice + Payment via InvoiceService
    string? invoiceId = null;
    string? invoiceNumber = null;

    if (!isCredit)
    {
        var invoiceNotes = string.IsNullOrWhiteSpace(notes)
            ? $"POS walk-in: {session.ClassName} on {StudioTime.Local(session.StartTime):yyyy-MM-dd HH:mm}"
            : notes;

        var invoice = new Invoice
        {
            ClientId = clientId,
            TotalDiscount = 0m,
            TotalTax = 0m,
            IssueDate = DateTime.UtcNow,
            Notes = invoiceNotes,
            Lines = new List<InvoiceLine>
            {

        {
            new InvoiceLine
            {
                ProductId = session.ClassBlueprintId ?? string.Empty,
                Description = ClassFormatLabel(session.Format),
                Quantity = 1,
                // Use the net (post-discount) price as UnitPrice so the
                // invoice total reflects what the client actually owes.
                UnitPrice = amount > 0 ? amount : expectedPrice,
                // Record the referral discount amount for auditability.
                LineDiscount = discountAmount,
                AttendanceId = attendance.Id,
                CalendarSessionId = sessionId,
                ProductTypeSnapshot = "CLASS",
            }
        }
    };

    var createdInvoice = await invoiceService.CreateInvoiceAsync(invoice);
    invoiceId = createdInvoice.Id;
    invoiceNumber = createdInvoice.InvoiceNumber;

    // Add payment (if amount > 0)
    if (amount > 0)
    {
        var payment = new Payment
        {
            AmountPaid = amount,
            PaymentDate = DateTime.UtcNow,
            PaymentMethod = string.IsNullOrWhiteSpace(paymentMethod) ? "CASH" : paymentMethod,
        };
        await invoiceService.AddPaymentAsync(createdInvoice.Id!, payment);
    }
}
else
{
