public async Task<IEnumerable<ClientPackage>> GetActivePackagesForClientAsync(string clientId, string format)
{
    // A package with ExpiryDate == null never expires; include it unconditionally.
    // A package with a concrete ExpiryDate must still be in the future.
    var noExpiry  = Builders<ClientPackage>.Filter.Eq(p => p.ExpiryDate, (DateTime?)null);
    var notExpired = Builders<ClientPackage>.Filter.Gt(p => p.ExpiryDate, DateTime.UtcNow);
    var expiryOk  = Builders<ClientPackage>.Filter.Or(noExpiry, notExpired);

    // MAT is a sub-type of group class. A MAT session can be paid with either a
    // MAT-specific package (preferred — consumed first) or a generic GROUP package
    // (fallback). Exact matches on other formats (PRIVATE, DUO, FREELANCE) are kept
    // strict so packages are never cross-consumed across incompatible class types.
    var upper = (format ?? "").ToUpperInvariant();
    var formatFilter = upper == "MAT"
        ? Builders<ClientPackage>.Filter.In(p => p.Format, new[] { "MAT", "GROUP" })
        : Builders<ClientPackage>.Filter.Eq(p => p.Format, upper == "" ? format : upper);

    var filter = Builders<ClientPackage>.Filter.And(
        Builders<ClientPackage>.Filter.Eq(p => p.ClientId, clientId),
        formatFilter,
        // Include LOW_BALANCE alongside ACTIVE: a package with ≤2 credits
