/// canonical Type string. Returns:
///   - mappedType: the entity's <c>Type</c> ("PACKAGE", "MERCHANDISE"); null on unknown.
///   - formatOverride: forces <see cref="Product.FormatRestriction"/> regardless of the
///     sheet's format_restriction column (used for "Private" → PACKAGE+PRIVATE).
///   - skip: true if this row should be intentionally skipped.
///   - skipReason: human-readable reason if <c>skip</c> is true.
///
/// V2: class/private/rental/freelance sheet types are now skipped because
/// class pricing lives on ClassBlueprint.DropInPrice and freelance scheduling
/// runs through the blueprint's IsFreelance flag.
/// </summary>
internal static (string? mappedType, string? formatOverride, bool skip, string? skipReason) MapSheetType(string raw)
{
    var key = (raw ?? string.Empty).Trim().ToLowerInvariant();
    return key switch
    {
        "class" => (null, null, true, "V2: class pricing now lives on ClassBlueprint — skipped."),
        "private" => (null, null, true, "V2: private class pricing now lives on ClassBlueprint — skipped."),
        "rental" => (null, null, true, "V2: rental product type deprecated — skipped."),
        "freelance" or "freelance1" => (null, null, true, "V2: freelance pricing now lives on ClassBlueprint — skipped."),
        "freelance package" or "freelance_package" or "freelancepackage" =>
            (null, null, true, "V2: freelance package type deprecated — skipped."),
        "package" => ("PACKAGE", null, false, null),
        "merchandise" => ("MERCHANDISE", null, false, null),
        _ => (null, null, false, null),
    };
}

/// <summary>Maps the sheet's free-form format-restriction label to the entity enum string.</summary>
private static string MapFormatRestriction(string? raw)
{
    var key = (raw ?? string.Empty).Trim().ToLowerInvariant();
    return key switch
    {
        "group" => "GROUP",
        "private" => "PRIVATE",
        "mixed" => "MIXED",
        "none" or "" => "NONE",
        _ => "NONE",
    };
}

/// <summary>Splits semicolon-delimited variants, trimming and dropping empties. Returns empty list on null/empty input.</summary>
private static List<string> ParseVariants(string? raw)
{
    if (string.IsNullOrWhiteSpace(raw)) return new List<string>();
    return raw
        .Split(';', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries)
        .ToList();
}

/// <summary>
/// P3-S14: Splits an existing flat <see cref="Product.StockQuantity"/> evenly across the
/// product's <c>Variants</c> labels (Q3-S14-3=A). Any remainder lands on the first variant
/// so the total reconciles exactly. Returns <c>(variantLabel, stock)</c> pairs ready for
/// SKU insertion.
/// </summary>
/// <example>30 across ["Black", "Navy", "White"] → [(Black, 10), (Navy, 10), (White, 10)].</example>
/// <example>31 across the same → [(Black, 11), (Navy, 10), (White, 10)].</example>
public static List<(string Variant, int Stock)> SplitStockAcrossVariants(int totalStock, List<string> variants)
{
    if (variants is null || variants.Count == 0) return new List<(string, int)>();
    if (totalStock < 0) totalStock = 0;

    var n = variants.Count;
    var basePer = totalStock / n;
    var remainder = totalStock % n;

    var result = new List<(string Variant, int Stock)>(n);
    for (var i = 0; i < n; i++)
    {
        var stock = basePer + (i == 0 ? remainder : 0);
        result.Add((variants[i], stock));
    }
    return result;
}

