/// </summary>
internal static (string? Color, string? Size) ParseVariantLabel(string label)
{
    if (string.IsNullOrWhiteSpace(label)) return (null, null);
    var trimmed = label.Trim();
    var slash = trimmed.IndexOf('/');
    if (slash < 0) return (trimmed, null);

