    public async Task<bool> MarkInvoicePaidByIdAsync(string invoiceId, string paymentIntentId)
    {
        var invoice = await _invoices.Find(i => i.Id == invoiceId).FirstOrDefaultAsync();
        if (invoice == null)
        {
            _logger.LogWarning("MarkInvoicePaidByIdAsync: invoice {InvoiceId} not found.", invoiceId);
