        var payment = new SoulPilates.Core.Entities.Payment
        {
            InvoiceId = invoiceId,
            PaymentDate = DateTime.UtcNow,
            AmountPaid = invoice.TotalNet,
            PaymentMethod = "STRIPE",
        };

